#include "yolo_int8.h"
#include "layers.h"          /* generated by yolov3_tiny_ref.py -> <out>/model/layers.h */
#include <string.h>

#define ALIGN 16u
#define MAX_OW INPUT_W       /* widest conv output row (accumulator row) */

static int8_t  s_input[INPUT_C * INPUT_H * INPUT_W];
static int8_t  s_arena[YOLO_ARENA_BYTES];
static int32_t s_off[NUM_LAYERS];     /* byte offset of each layer's output in s_arena */
static int     s_ready;

static size_t out_elems(const layer_t *L) { return (size_t)L->c_out * L->h_out * L->w_out; }
static size_t align_up(size_t v) { return (v + ALIGN - 1) & ~(size_t)(ALIGN - 1); }

/* ---------------------------------------------------------------- memory planning */
int yolo_init(size_t *peak_bytes)
{
    int owner[NUM_LAYERS], last[NUM_LAYERS];
    size_t peak = 0;
    int i, j;

    for (i = 0; i < NUM_LAYERS; i++) {
        const layer_t *L = &LAYERS[i];
        owner[i] = i;
        if (L->type == L_YOLO || (L->type == L_ROUTE && L->src1 < 0))
            owner[i] = owner[L->type == L_YOLO ? i - 1 : L->src0];     /* pure alias, no copy */
        if (L->type == L_CONV && L->w_out > MAX_OW) return -1;
    }
    for (i = 0; i < NUM_LAYERS; i++) last[i] = i;
    for (i = 0; i < NUM_LAYERS; i++) {
        const layer_t *L = &LAYERS[i];
        if (L->type == L_ROUTE) {
            if (last[owner[L->src0]] < i) last[owner[L->src0]] = i;
            if (L->src1 >= 0 && last[owner[L->src1]] < i) last[owner[L->src1]] = i;
        } else if (i > 0 && last[owner[i - 1]] < i) {
            last[owner[i - 1]] = i;
        }
        /* the raw yolo inputs are read by the decode after the last layer: keep them alive to the end */
        if (L->type == L_YOLO) last[owner[i - 1]] = NUM_LAYERS;
    }
    for (i = 0; i < NUM_LAYERS; i++) {
        size_t size, cand, best = (size_t)-1;
        int k;
        if (owner[i] != i) { s_off[i] = s_off[owner[i]]; continue; }
        size = align_up(out_elems(&LAYERS[i]));
        /* first-fit: candidate start = 0 or the end of a buffer that is still live at layer i */
        for (k = -1; k < i; k++) {
            int clash = 0;
            cand = 0;
            if (k >= 0) {
                if (owner[k] != k || last[k] < i) continue;
                cand = (size_t)s_off[k] + align_up(out_elems(&LAYERS[k]));
            }
            for (j = 0; j < i; j++) {
                if (owner[j] != j || last[j] < i) continue;
                if (cand < (size_t)s_off[j] + align_up(out_elems(&LAYERS[j])) && (size_t)s_off[j] < cand + size) { clash = 1; break; }
            }
            if (!clash && cand < best) best = cand;
        }
        if (best + size > YOLO_ARENA_BYTES) return -1;
        s_off[i] = (int32_t)best;
        if (best + size > peak) peak = best + size;
    }
    s_ready = 1;
    if (peak_bytes) *peak_bytes = peak;
    return 0;
}

int8_t *yolo_input(void) { return s_input; }

void yolo_quantize_f32(const float *x, int8_t *q, size_t n)
{
    size_t i;
    for (i = 0; i < n; i++) {
        double t = (double)x[i] * (double)(1 << INPUT_FA) + 0.5;     /* round half up */
        long long f = (long long)t;
        if ((double)f > t) f--;                                       /* floor */
        q[i] = (int8_t)(f > 127 ? 127 : (f < -128 ? -128 : f));
    }
}

const int8_t *yolo_layer_output(int idx) { return s_arena + s_off[idx]; }

/* ---------------------------------------------------------------- layer kernels */
static void conv_layer(const layer_t *L, const int8_t *in, int8_t *out, const int8_t *w, const int32_t *bias)
{
    const int C = L->c_in, H = L->h_in, W = L->w_in, O = L->c_out, OH = L->h_out, OW = L->w_out;
    const int K = L->k, S = L->stride, P = L->pad, sh = L->shift;
    int32_t acc[MAX_OW];
    int oc, oy, ox, ic, ky, kx;

    for (oc = 0; oc < O; oc++) {
        const int8_t *wo = w + (size_t)oc * C * K * K;
        for (oy = 0; oy < OH; oy++) {
            for (ox = 0; ox < OW; ox++) acc[ox] = bias[oc];
            for (ic = 0; ic < C; ic++) {
                for (ky = 0; ky < K; ky++) {
                    const int iy = oy * S + ky - P;
                    const int8_t *row;
                    if (iy < 0 || iy >= H) continue;                  /* zero padding row */
                    row = in + ((size_t)ic * H + iy) * W;
                    for (kx = 0; kx < K; kx++) {
                        const int32_t wt = wo[((size_t)ic * K + ky) * K + kx];
                        const int lo = (kx >= P) ? 0 : (P - kx + S - 1) / S;
                        const int num = W - 1 + P - kx;
                        int hi = (num < 0) ? 0 : num / S + 1;          /* exclusive */
                        if (hi > OW) hi = OW;
                        for (ox = lo; ox < hi; ox++) acc[ox] += wt * row[ox * S + kx - P];
                    }
                }
            }
            for (ox = 0; ox < OW; ox++) {
                int32_t v = acc[ox];
                if (sh > 0)      v = (v + (1 << (sh - 1))) >> sh;      /* round half up */
                else if (sh < 0) v = v * (1 << -sh);
                if (L->act == ACT_RELU)       { if (v < 0) v = 0; }
                else if (L->act == ACT_LEAKY) { if (v < 0) v = (v * 13 + 64) >> 7; }   /* ~0.1 */
                out[((size_t)oc * OH + oy) * OW + ox] = (int8_t)(v > 127 ? 127 : (v < -128 ? -128 : v));
            }
        }
    }
}

static void maxpool_layer(const layer_t *L, const int8_t *in, int8_t *out)
{
    const int lp = L->pad / 2;                  /* darknet: pad split left = pad/2, rest on the right/bottom */
    int c, oy, ox, ky, kx;
    for (c = 0; c < L->c_in; c++)
        for (oy = 0; oy < L->h_out; oy++)
            for (ox = 0; ox < L->w_out; ox++) {
                int m = -128;
                for (ky = 0; ky < L->k; ky++) {
                    const int iy = oy * L->stride + ky - lp;
                    if (iy < 0 || iy >= L->h_in) continue;
                    for (kx = 0; kx < L->k; kx++) {
                        const int ix = ox * L->stride + kx - lp;
                        int v;
                        if (ix < 0 || ix >= L->w_in) continue;
                        v = in[((size_t)c * L->h_in + iy) * L->w_in + ix];
                        if (v > m) m = v;
                    }
                }
                out[((size_t)c * L->h_out + oy) * L->w_out + ox] = (int8_t)m;
            }
}

static void upsample_layer(const layer_t *L, const int8_t *in, int8_t *out)
{
    const int s = L->stride;
    int c, y, x;
    for (c = 0; c < L->c_in; c++)
        for (y = 0; y < L->h_out; y++)
            for (x = 0; x < L->w_out; x++)
                out[((size_t)c * L->h_out + y) * L->w_out + x] = in[((size_t)c * L->h_in + y / s) * L->w_in + x / s];
}

/* ---------------------------------------------------------------- network */
int yolo_forward(const int8_t *weights, const int32_t *bias, yolo_layer_cb cb, void *user)
{
    int i;
    if (!s_ready) return -1;
    for (i = 0; i < NUM_LAYERS; i++) {
        const layer_t *L = &LAYERS[i];
        const int8_t *in = (i == 0) ? s_input : s_arena + s_off[i - 1];
        int8_t *out = s_arena + s_off[i];

        switch (L->type) {
        case L_CONV:    conv_layer(L, in, out, weights + L->w_off, bias + L->b_off); break;
        case L_MAXPOOL: maxpool_layer(L, in, out); break;
        case L_UPSAMPLE: upsample_layer(L, in, out); break;
        case L_ROUTE:
            if (L->src1 >= 0) {                  /* concat along channels (CHW => contiguous blocks) */
                size_t n0 = out_elems(&LAYERS[L->src0]), n1 = out_elems(&LAYERS[L->src1]);
                memcpy(out, s_arena + s_off[L->src0], n0);
                memcpy(out + n0, s_arena + s_off[L->src1], n1);
            }                                    /* single source: alias, nothing to do */
            break;
        case L_YOLO: break;                      /* decode happens outside, on the raw conv output */
        default: return -1;
        }
        if (cb && L->type != L_YOLO) cb(i, out, out_elems(L), user);
    }
    return 0;
}
